css:
/* Recibo de Vencimento / Payslip — Isoft Angola HR.
   A4 portrait, one copy per page. Targets wkhtmltopdf (Qt WebKit): tables, pt units,
   no flexbox or grid. Everything is scoped to .rv so no other print format is touched.

   The four .print-format margin declarations below are read by
   frappe.utils.pdf.read_options_from_html and become the wkhtmltopdf page margins, so
   the printable area is the same on every site whatever Print Settings say. */
.print-format {
  margin-top: 10mm;
  margin-bottom: 10mm;
  margin-left: 12mm;
  margin-right: 12mm;
}

/* Frappe's print stylesheet pads .print-format by 0.2in top and bottom in a narrow
   viewport — and wkhtmltopdf's viewport is narrow. The page margins above already
   frame the page; the padding only took ~29pt out of every page and, once a copy was
   full, pushed an empty third page out of the printer. */
@media print {
  .print-format { padding: 0 !important; margin: 0 !important; }
}

.rv {
  font-family: "Liberation Sans", Arial, Helvetica, sans-serif;
  font-size: 8.2pt;
  line-height: 1.25;
  color: #111;
  width: 100%;
  -webkit-print-color-adjust: exact;
}
.rv table { border-collapse: collapse; width: 100%; }
.rv td, .rv th { vertical-align: top !important; }

/* ---- counter Frappe's print stylesheet (padding 6px, grey th, no th border: all
        !important) at the same weight, scoped to the receipt ---- */
.rv td, .rv th { padding: 0 !important; }
.rv th { background-color: transparent !important; border-bottom: 0 !important; }

.rv .rv-strong { font-weight: bold; }
.rv .rv-muted { color: #555; }
.rv .rv-mono { font-family: "Liberation Mono", "DejaVu Sans Mono", monospace; letter-spacing: .2pt; }

/* ---- copies ---- */
.rv .rv-break { page-break-before: always; }

/* ---- header ---- */
.rv .rv-head { margin-bottom: 5pt; border-bottom: 1.6pt solid #1a1a1a; }
.rv .rv-head td { padding: 0 0 5pt 0 !important; }
.rv .rv-head-co { width: 50%; }
.rv .rv-head-doc { width: 50%; text-align: right; }
.rv .rv-co { width: auto; }
.rv .rv-co td { padding: 0 !important; vertical-align: middle !important; }
/* An explicit cell width: Frappe's print stylesheet gives every image max-width:100%,
   and 100% of an auto-sized cell is whatever WebKit felt like — once it was 1pt. */
.rv .rv-co-name { font-size: 12.5pt; font-weight: bold; letter-spacing: .3pt; margin-bottom: 1.5pt; }
.rv .rv-co-line { font-size: 8pt; word-wrap: break-word; }
.rv .rv-title {
  font-size: 14pt; font-weight: bold; letter-spacing: 1pt; text-transform: uppercase;
  color: #1a1a1a; margin-bottom: 3pt; white-space: nowrap;
}
.rv .rv-copy-label {
  display: inline-block; border: 1pt solid #1a1a1a; padding: 1.5pt 6pt !important;
  font-size: 7.6pt; font-weight: bold; letter-spacing: .8pt; text-transform: uppercase;
  margin-bottom: 5pt; white-space: nowrap;
}
.rv .rv-doc-meta { width: auto; margin-left: auto; }
.rv .rv-doc-meta td { padding: .6pt 0 !important; font-size: 8pt; }
.rv .rv-doc-meta .k { color: #555; padding-right: 8pt !important; text-align: right; }
.rv .rv-doc-meta .v { font-weight: bold; text-align: right; white-space: nowrap; }

/* ---- stamps ---- */
.rv .rv-stamp {
  border: 1.2pt solid #b00020; color: #b00020; padding: 3pt 6pt !important; margin: 0 0 7pt 0;
  font-weight: bold; font-size: 9pt; text-align: center; letter-spacing: 1.5pt;
}

/* ---- section captions ---- */
.rv .rv-sec-title {
  font-size: 7.6pt; font-weight: bold; text-transform: uppercase; letter-spacing: .9pt;
  color: #333; background: #ededed; padding: 1.8pt 5pt; margin: 4pt 0 2pt 0;
  border-left: 2.4pt solid #1a1a1a;
}

/* ---- key / value grid ---- */
.rv .rv-kv td { padding: 1.5pt 4pt !important; border-bottom: .5pt solid #dcdcdc; font-size: 8pt; }
.rv .rv-kv .k { width: 16%; color: #555; }
.rv .rv-kv .v { width: 34%; word-wrap: break-word; }
.rv .rv-kv-1 .k { width: 38%; }
.rv .rv-kv-1 .v { width: 62%; }

/* ---- processing stat boxes ---- */
.rv .rv-stats td {
  padding: 2.5pt 5pt !important; border: .6pt solid #cfcfcf; background: #fafafa;
  text-align: center; width: 20%;
}
.rv .rv-stats .k { font-size: 7pt; color: #555; text-transform: uppercase; letter-spacing: .4pt; }
.rv .rv-stats .v { font-size: 9.2pt; font-weight: bold; margin-top: 1pt; white-space: nowrap; }

/* ---- earnings / deductions ---- */
.rv .rv-lines { table-layout: fixed; margin-bottom: 2pt; }
.rv .rv-lines thead { display: table-header-group; }
.rv .rv-lines th {
  font-size: 7.4pt; font-weight: bold; text-transform: uppercase; letter-spacing: .5pt;
  color: #333; text-align: left; padding: 2pt 5pt !important;
  border-top: .9pt solid #1a1a1a; border-bottom: .9pt solid #1a1a1a !important;
}
.rv .rv-lines td { padding: 1.8pt 5pt !important; border-bottom: .5pt solid #dcdcdc; word-wrap: break-word; }
.rv .rv-lines .c-code { width: 13%; white-space: nowrap; }
.rv .rv-lines .c-desc { width: 59%; }
.rv .rv-lines .c-amt { width: 28%; text-align: right; white-space: nowrap; }
.rv .rv-lines th.c-amt { text-align: right; }
.rv .rv-lines .rv-memo td { color: #666; font-style: italic; }
.rv .rv-lines .rv-memo-tag { font-size: 7pt; }
.rv .rv-lines .rv-empty td { text-align: center; color: #888; }
.rv .rv-lines tfoot .rv-total td {
  font-weight: bold; border-top: .9pt solid #1a1a1a; border-bottom: 0; padding-top: 2.5pt !important;
  text-align: right;
}
.rv .rv-lines tr { page-break-inside: avoid; }

/* ---- warning ---- */
.rv .rv-warn {
  border: 1pt solid #b00020; color: #b00020; padding: 3pt 6pt !important; margin: 6pt 0 0 0;
  font-weight: bold; font-size: 7.8pt;
}

/* ---- payment + summary ---- */
.rv .rv-bottom { margin-top: 2pt; page-break-inside: avoid; }
.rv .rv-bottom > tbody > tr > td { padding: 0 !important; }
.rv .rv-pay { width: 50%; padding-right: 10pt !important; }
.rv .rv-sum { width: 50%; padding-left: 10pt !important; }
.rv .rv-summary td { padding: 1.7pt 5pt !important; border-bottom: .5pt solid #dcdcdc; font-size: 8.2pt; }
.rv .rv-summary .k { color: #333; }
.rv .rv-summary .v { text-align: right; white-space: nowrap; font-weight: bold; width: 38%; }
.rv .rv-summary .rv-net td {
  background: #1a1a1a; color: #fff; font-weight: bold; font-size: 9.8pt;
  padding: 4pt 6pt !important; border-bottom: 0; text-transform: uppercase; letter-spacing: .5pt;
}
.rv .rv-summary .rv-net .k { color: #fff; white-space: nowrap; }

/* ---- confirmation ---- */
.rv .rv-decl { font-style: italic; margin: 2pt 0 8pt 0; padding: 0 4pt; }
.rv .rv-sign { page-break-inside: avoid; }
.rv .rv-sign td { padding: 0 !important; }
.rv .rv-sign-l { width: 55%; }
.rv .rv-sign-gap { width: 45%; }
.rv .rv-sign-line { border-bottom: .8pt solid #1a1a1a; height: 11pt; }
.rv .rv-sign-cap { font-size: 7.6pt; color: #333; margin-top: 2pt; }

/* ---- footer ---- */
.rv .rv-foot { margin-top: 5pt; border-top: .5pt solid #bbb; }
.rv .rv-foot td { padding: 2pt 0 0 0 !important; font-size: 6.8pt; color: #666; }
.rv .rv-foot-r { text-align: right; }

@media print {
  .rv table, .rv tr { page-break-inside: avoid; }
  .rv thead { display: table-header-group; }
}
